import base64, hashlib, os, subprocess, sys, zlib
from pathlib import Path

source_dir=Path('/kaggle/working/edgelegal')
for name, encoded in {'backend/app/logging_config.py': '', 'backend/app/evaluate_held_out.py': '', 'backend/app/held_out_metrics.py': '', 'backend/app/llm/prompts.py': '', 'backend/app/triage_model/__init__.py': 'eJwDAAAAAAE=', 'backend/app/triage_model/model.py': '', 'backend/app/triage_model/infer.py': '', 'backend/app/triage_model/dataset.py': '', 'backend/app/triage_model/train_document.py': ''}.items():
    path=source_dir/name
    path.parent.mkdir(parents=True,exist_ok=True)
    path.write_bytes(zlib.decompress(base64.b64decode(encoded)))
import torch
assert torch.cuda.is_available(), 'GPU required'
print(torch.cuda.get_device_name(0),flush=True)
subprocess.run([sys.executable,'-m','pip','install','-q','transformers==5.20.2','sentencepiece'],check=True)
data=next(p.parent for p in Path('/kaggle/input').rglob('best_document.pt') if (p.parent/'test.json').exists())
old=next(Path('/kaggle/input').rglob('best_model.pt'))
diagnostic=next(data.glob('C_finetuned_triage_*.json'))
for name,digest in {'best_document.pt': '1fa9dc54a46cb58a1475a604e9975201eb50680abcbb8f63ca13d155ad4c5b0c', 'manifest.json': 'e98e90e8e52a54b9c10b71c237108dc8d8fe546db37d73ea488b12163fef71ed', 'dev_predictions.json': '1560ec37149348c5a860e27949f9019b542ce2851e29d2fdecc56e327c377042', 'dev.json': 'ec35aa76c04debfba8e4bc813a3eacde1727a03871cff71c8f60b4dbb37cf15d', 'test.json': 'd1b4c170db11ce33d4da990050bfe79cbb07d6a66bc899679ac5082dbc4de5a0', 'C_finetuned_triage_20260927T143308+0000.json': 'b6cb1c73193acac1a5e20b0af3f407f64304be2ed8faf7fe59a39902daf9dbd8', 'best_model.pt': '7ea45d37671897f04267f5a9e187a28790631362c8231c99757db620da1cbc61'}.items():
    path=old if name=='best_model.pt' else diagnostic if name.startswith('C_finetuned_triage_') else data/name
    with path.open('rb') as stream:
        assert hashlib.file_digest(stream,'sha256').hexdigest()==digest,name
os.chdir(source_dir)
subprocess.run([sys.executable,'-u','-m','backend.app.evaluate_held_out',
    '--data',str(data),'--diagnostic',str(diagnostic),
    '--checkpoint',str(old),'--candidate',str(data/'best_document.pt'),'--development',str(data/'dev_predictions.json'),
    '--provider-model','openai/gpt-oss-20b','--out','/kaggle/working/held-out','--document-only'],check=True)

